import csv
import json

# Read budget.json to get mapping from budget_id to event_id
with open('json/budget.json', 'r') as f:
    budget_data = json.load(f)

budget_to_event = {}
for record in budget_data['records']:
    budget_to_event[record['budget_id']] = record['link_to_event']

# Find budget_ids for October Meeting event (recggMW2eyCYceNcy)
october_meeting_event_id = 'recggMW2eyCYceNcy'
budget_ids_for_event = [bid for bid, eid in budget_to_event.items() if eid == october_meeting_event_id]
print(f"Budget IDs for October Meeting: {budget_ids_for_event}")

# Read expense.csv and filter by approved=True and link_to_budget in budget_ids_for_event
expenses = []
with open('csv/expense.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        if row['approved'] == 'true' and row['link_to_budget'] in budget_ids_for_event:
            expenses.append({
                'description': row['expense_description'],
                'cost': float(row['cost']),
                'category': budget_to_event.get(row['link_to_budget'])  # This will be None, need category from budget
            })

print(f"\nExpenses for October Meeting:")
for e in expenses:
    print(e)

# Get categories from budget data
exp_with_category = []
for row in expenses:
    for bid, eid in budget_to_event.items():
        if eid == october_meeting_event_id:
            for rec in budget_data['records']:
                if rec['budget_id'] == bid:
                    exp_with_category.append({
                        'type': rec['category'],
                        'cost': row['cost']
                    })
                    break

print(f"\nExpenses with categories:")
for e in exp_with_category:
    print(e)

# Group by type and sum
total_by_type = {}
for e in exp_with_category:
    t = e['type']
    c = e['cost']
    if t not in total_by_type:
        total_by_type[t] = 0
    total_by_type[t] += c

print(f"\nTotal by type:")
for t, total in total_by_type.items():
    print(f"{t}: {total}")

